const rows = $input.all().map(function (item) { return item.json; });
const out = [];
const now = new Date();
const todayUtc = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
const skip = ['paid', 'void', 'cancelled', 'canceled', 'closed', 'written off'];
for (const row of rows) {
  const status = String(row['Status'] || '').trim().toLowerCase();
  if (skip.indexOf(status) !== -1) continue;
  const email = String(row['Client Email'] || '').trim();
  if (email.indexOf('@') === -1) continue;
  const rawAmount = row['Amount Due'] !== undefined && row['Amount Due'] !== '' ? row['Amount Due'] : row['Amount (in USD)'];
  const amount = Number(String(rawAmount === undefined || rawAmount === null ? '' : rawAmount).replace(/[^0-9.]/g, ''));
  if (!isFinite(amount) || amount <= 0) continue;
  const dueRaw = row['Due Date'];
  let dueUtc = NaN;
  if (typeof dueRaw === 'number' && dueRaw > 0) {
    dueUtc = Date.UTC(1899, 11, 30) + Math.round(dueRaw) * 86400000;
  } else {
    const text = String(dueRaw === undefined || dueRaw === null ? '' : dueRaw).trim();
    const m = text.match(/([0-9]{4})-([0-9]{2})-([0-9]{2})/);
    if (m) {
      dueUtc = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    } else {
      const parsed = new Date(text);
      if (!isNaN(parsed.getTime())) {
        dueUtc = Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
      }
    }
  }
  if (isNaN(dueUtc)) continue;
  const days = Math.floor((todayUtc - dueUtc) / 86400000);
  if (days < 1) continue;
  const lastRaw = row['Last Follow-Up Date'];
  let lastUtc = NaN;
  if (typeof lastRaw === 'number' && lastRaw > 0) {
    lastUtc = Date.UTC(1899, 11, 30) + Math.round(lastRaw) * 86400000;
  } else {
    const lastText = String(lastRaw === undefined || lastRaw === null ? '' : lastRaw).trim();
    const lm = lastText.match(/([0-9]{4})-([0-9]{2})-([0-9]{2})/);
    if (lm) {
      lastUtc = Date.UTC(Number(lm[1]), Number(lm[2]) - 1, Number(lm[3]));
    } else if (lastText) {
      const lastParsed = new Date(lastText);
      if (!isNaN(lastParsed.getTime())) {
        lastUtc = Date.UTC(lastParsed.getFullYear(), lastParsed.getMonth(), lastParsed.getDate());
      }
    }
  }
  if (!isNaN(lastUtc) && (todayUtc - lastUtc) / 86400000 < 7) continue;
  const invoiceNo = String(row['Invoice #'] !== undefined ? row['Invoice #'] : row['Invoice ID'] || '').trim();
  if (!invoiceNo) continue;
  const client = String(row['Client Name'] || '').trim();
  if (!client) continue;
  const company = String(row['Company'] || client).trim();
  const tone = days <= 14 ? 'Friendly Reminder' : days <= 30 ? 'Firm & Direct' : 'Urgent / Solution-Oriented';
  const amountDisplay = '$' + amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const paymentLink = String(row['Payment Link'] || '').trim();
  const item = Object.assign({}, row, {
    'Client Name': client,
    'Company': company,
    'Invoice #': invoiceNo,
    'Amount Due': amount,
    'Amount Display': amountDisplay,
    'Days Past Due': days,
    'Due Date': String(dueRaw === undefined || dueRaw === null ? '' : dueRaw),
    'Tone': tone,
    'Payment Link': paymentLink
  });
  out.push({ json: item });
}
return out;

