const nl = String.fromCharCode(10);
const signature = 'Regards,' + nl + '[Billing Team]';
const source = $('Normalize & Filter Invoices').item.json;
let parsed = $json.output;
if (typeof parsed === 'string') {
  try {
    parsed = JSON.parse(parsed);
  } catch (e) {
    parsed = {};
  }
}
if (!parsed || typeof parsed !== 'object') parsed = {};
let subject = String(parsed.email_subject || '').trim();
let body = String(parsed.email_body || '').trim();
subject = subject.split('```').join('').split('**').join('').trim();
body = body.split('```').join('').split('**').join('').trim();
const banned = ['[Your Name]', '[Client Name]', '[Company]', '[Invoice Number]', '[Amount Due]', '[Amount]', '[Date]', '[Payment Link]'];
for (const token of banned) {
  body = body.split(token).join('');
  subject = subject.split(token).join('');
}
const backslash = String.fromCharCode(92);
body = body.split(backslash + 'n').join(nl).trim();
const cut = body.lastIndexOf('Regards,');
if (cut !== -1) body = body.slice(0, cut).trim();
const first = String(source['Client Name'] || 'there').split(' ')[0];
const invoiceNo = String(source['Invoice #'] || '');
const amount = String(source['Amount Display'] || '');
const days = source['Days Past Due'];
const dueDate = String(source['Due Date'] || '');
const link = String(source['Payment Link'] || '');
const tone = String(source['Tone'] || '');
if (!body) {
  if (tone === 'Friendly Reminder') {
    body = 'Hi ' + first + ', just a friendly reminder that invoice ' + invoiceNo + ' for ' + amount + ' was due on ' + dueDate + '. If it is already on its way, please disregard this note.';
    if (link) body = body + ' You can settle it here: ' + link + '.';
  } else if (tone === 'Firm & Direct') {
    body = 'Hi ' + first + ', invoice ' + invoiceNo + ' for ' + amount + ' is now ' + days + ' days past due.';
    body = link ? body + ' Please confirm the payment date or settle the balance here: ' + link + '.' : body + ' Please confirm the payment date.';
  } else {
    body = 'Hi ' + first + ', invoice ' + invoiceNo + ' for ' + amount + ' is now ' + days + ' days past due and I would like to get this resolved. If paying in full is not possible right now, reply with a date and amount that works and we can set up a payment plan.';
  }
}
if (!subject) subject = 'Invoice ' + invoiceNo + ' - ' + days + ' days overdue';
body = body.trim() + nl + nl + signature;
const plain = body.split('Regards,')[0];
const scrub = plain.replace(/https?:[^ ]+/g, ' ').replace(/\$[0-9][0-9,]*\.[0-9][0-9]/g, ' ');
const sentences = scrub.match(/[.!?]/g);
const sentenceCount = sentences ? sentences.length : 0;
return {
  json: Object.assign({}, source, {
    email_subject: subject,
    email_body: body,
    email_json: JSON.stringify({ email_subject: subject, email_body: body }),
    'Sentence Count': sentenceCount
  })
};
